from rules import amount


def solve(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}

    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue

        if "id" in event:
            identity = ("id", event["id"])
        else:
            identity = ("anonymous", position)

        revision = event.get("revision", 0)
        previous = winners.get(identity)
        if previous is None or (revision, position) >= (previous[0], previous[1]):
            winners[identity] = (revision, position, event)

    balances = dict(data.get("opening", {}))
    for _, _, event in winners.values():
        if event.get("void", False):
            continue
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances[key] = balances.get(key, 0) + amount(event, data["rounding"])

    return {"balances": balances}

def _round_ratio(numerator, denominator, mode):
    if mode == "floor":
        return numerator // denominator
    if mode == "half_up":
        return (2 * numerator + denominator) // (2 * denominator)
    raise ValueError(f"unsupported rounding mode: {mode}")


def amount(event, mode):
    price_quantity = event["price"] * event.get("quantity", 1)
    discount_bp = max(0, min(10000, event.get("discount_bp", 0)))
    net = _round_ratio(price_quantity * (10000 - discount_bp), 10000, mode)

    tax_bp = event.get("tax_bp", 0)
    tax = _round_ratio(net * tax_bp, 10000, mode)
    total = net + tax
    return -total if event.get("kind") == "refund" else total
